import ReportingCarbonAnalyticsPanel, {
  type ReportingCarbonFootprintPayload,
  type ReportingComparisonsPayload,
} from './reporting/ReportingCarbonAnalyticsPanel';
import { HIDE_ISO_14067_UI } from '../constants/uiVisibility';
import { frameworkReadinessLabel, readinessTypeHint } from '../constants/reportReadinessLabels';
import {
  REPORTING_TAB,
  REPORTING_TAB_COUNT,
} from '../constants/reportingTabs';
import {
  axisTickForMode,
  cartesianGridStroke,
  chartAnimationPropsFor,
  rechartsLegendProps,
  rechartsTooltipProps,
} from '../theme/rechartsAppearances';
import {
  CO2E_METHODOLOGY_SUBTITLE,
  GHG_SCOPE_COLORS,
  GHG_SCOPE_HEX,
  fillHexForScopeLabel,
  formatAxisTickKg,
  maxKgFromRows,
  rechartsEmissionsTooltipFormatter,
  rechartsKgValueAxisLabelProps,
  rechartsPercentTooltipFormatter,
  rechartsScoreAxisLabelProps,
  rechartsTonnesAxisLabelProps,
  rechartsTonnesTooltipFormatter,
  cartesianMarginsForKgAxis,
  pieChartCenterProps,
} from '../constants/carbonVisualization';
import CarbonChartFrame from './shared/CarbonChartFrame';
